(() => {
  const DEC = /^[0-9]+(\.[0-9]+)?$/;
  const pow10 = (n) => 10n ** BigInt(n);
  const parse = (value, name) => {
    if (typeof value !== "string" || !DEC.test(value)) {
      throw new Error("invalid decimal: " + name);
    }
    const dot = value.indexOf(".");
    if (dot < 0) return { v: BigInt(value), s: 0 };
    return { v: BigInt(value.slice(0, dot) + value.slice(dot + 1)), s: value.length - dot - 1 };
  };
  const add = (a, b) => {
    const s = Math.max(a.s, b.s);
    return { v: a.v * pow10(s - a.s) + b.v * pow10(s - b.s), s };
  };
  const isObj = (x) => x !== null && typeof x === "object" && !Array.isArray(x);
  function calculateGpa(input) {
    if (!isObj(input)) throw new Error("invalid input");
    for (const k of Object.keys(input)) {
      if (k !== "courses") throw new Error("unknown field: " + k);
    }
    const courses = input.courses;
    if (!Array.isArray(courses)) throw new Error("invalid courses");
    let N = { v: 0n, s: 0 };
    let D = { v: 0n, s: 0 };
    for (const c of courses) {
      if (!isObj(c)) throw new Error("invalid course");
      for (const k of Object.keys(c)) {
        if (k !== "gradePoints" && k !== "credits") throw new Error("unknown field: " + k);
      }
      const g = parse(c.gradePoints, "gradePoints");
      const cr = parse(c.credits, "credits");
      N = add(N, { v: g.v * cr.v, s: g.s + cr.s });
      D = add(D, cr);
    }
    if (D.v === 0n) return { gpa: null };
    const num = N.v * pow10(D.s) * 100n;
    const den = D.v * pow10(N.s);
    let q = num / den;
    const r = num % den;
    const twoR = 2n * r;
    if (twoR > den || twoR === den && q % 2n === 1n) q += 1n;
    const str = q.toString().padStart(3, "0");
    return { gpa: str.slice(0, -2) + "." + str.slice(-2) };
  }
  return { calculateGpa };
})()

