build.unitScript:
test("AC-1: 3.7, 3.3 and 2.0 weighted by 3, 3 and 2 credits gives 3.125, which rounds half to even to 3.12", () => {
  const result = code.calculateGpa({ courses: [
    { gradePoints: "3.7", credits: "3" },
    { gradePoints: "3.3", credits: "3" },
    { gradePoints: "2.0", credits: "2" }
  ] });
  assert.deepEqual(result, { gpa: "3.12" });
});
test("AC-2: 4.0, 3.0, 2.0 and 1.7 at 1 credit each gives exactly 2.675, which rounds to 2.68, not the float result 2.67", () => {
  const result = code.calculateGpa({ courses: [
    { gradePoints: "4.0", credits: "1" },
    { gradePoints: "3.0", credits: "1" },
    { gradePoints: "2.0", credits: "1" },
    { gradePoints: "1.7", credits: "1" }
  ] });
  assert.deepEqual(result, { gpa: "2.68" });
});
test("AC-3: a student with an empty course list gets a null GPA, not 0.00 and not an error", () => {
  assert.deepEqual(code.calculateGpa({ courses: [] }), { gpa: null });
});
test("a student whose courses all have zero credits gets a null GPA without dividing by zero", () => {
  const result = code.calculateGpa({ courses: [
    { gradePoints: "3.0", credits: "0" },
    { gradePoints: "4.0", credits: "0.0" }
  ] });
  assert.deepEqual(result, { gpa: null });
});
test("an extra field on the input or on a course throws an unknown field error naming that field", () => {
  assert.throws(() => code.calculateGpa({ courses: [], extra: "1" }), /^Error: unknown field: extra$/);
  assert.throws(() => code.calculateGpa({ courses: [{ gradePoints: "3.0", credits: "3", grade: "B" }] }), /^Error: unknown field: grade$/);
});
test("grade points or credits given as a number or as a non-decimal string throw an invalid decimal error naming the field", () => {
  assert.throws(() => code.calculateGpa({ courses: [{ gradePoints: 3.7, credits: "3" }] }), /^Error: invalid decimal: gradePoints$/);
  assert.throws(() => code.calculateGpa({ courses: [{ gradePoints: "3.7", credits: 3 }] }), /^Error: invalid decimal: credits$/);
  assert.throws(() => code.calculateGpa({ courses: [{ gradePoints: "3.7", credits: "three" }] }), /^Error: invalid decimal: credits$/);
});

